import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_max_reduce(torch::Tensor x, int64_t dim);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

#include <cmath>
#include <limits>
#include <type_traits>

using namespace cute;

template <typename scalar_t>
__device__ __forceinline__ scalar_t cute_shfl_down(
    scalar_t value,
    unsigned int offset)
{
    if constexpr (std::is_same<scalar_t, c10::Half>::value) {
        float value_float = static_cast<float>(value);
        float result_float = __shfl_down_sync(
            0xffffffff, value_float, offset);
        return static_cast<scalar_t>(result_float);
    } else {
        return __shfl_down_sync(0xffffffff, value, offset);
    }
}
template <typename scalar_t>
__device__ __forceinline__ scalar_t cute_max_combine(
    scalar_t a, scalar_t b)
{
    if (isnan(static_cast<double>(a))) {
        return a;
    }
    if (isnan(static_cast<double>(b))) {
        return b;
    }
    return b > a ? b : a;
}
template <typename scalar_t>
__global__ void cute_max_reduce_kernel(
    const scalar_t* __restrict__ x,
    scalar_t* __restrict__ y,
    int d0,
    int d1,
    int d2,
    int dim,
    int output_size)
{
    int output_idx = blockIdx.x;
    if (output_idx >= output_size) {
        return;
    }
    Tensor input = make_tensor(
        make_gmem_ptr(x),
        make_shape(d0, d1, d2),
        make_stride(d1 * d2, d2, Int<1>{}));
    scalar_t local_max = -std::numeric_limits<scalar_t>::infinity();
    if (dim == 0) {
        int i = output_idx / d2;
        int k = output_idx - i * d2;
        for (int r = threadIdx.x; r < d0; r += blockDim.x) {
            local_max = cute_max_combine(local_max, input(r, i, k));
        }
    } else if (dim == 1) {
        int b = output_idx / d2;
        int k = output_idx - b * d2;
        for (int r = threadIdx.x; r < d1; r += blockDim.x) {
            local_max = cute_max_combine(local_max, input(b, r, k));
        }
    } else {
        int b = output_idx / d1;
        int i = output_idx - b * d1;
        for (int r = threadIdx.x; r < d2; r += blockDim.x) {
            local_max = cute_max_combine(local_max, input(b, i, r));
        }
    }
    int lane = threadIdx.x & 31;
    int warp_id = threadIdx.x >> 5;
    for (int offset = 16; offset > 0; offset >>= 1) {
        scalar_t other = cute_shfl_down(local_max, offset);
        local_max = cute_max_combine(local_max, other);
    }
    extern __shared__ unsigned char shared_raw[];
    scalar_t* shared = reinterpret_cast<scalar_t*>(shared_raw);
    if (lane == 0) {
        shared[warp_id] = local_max;
    }
    __syncthreads();
    constexpr int num_warps = 8;
    if (warp_id == 0) {
        local_max = lane < num_warps
            ? shared[lane]
            : -std::numeric_limits<scalar_t>::infinity();
        for (int offset = 16; offset > 0; offset >>= 1) {
            scalar_t other = cute_shfl_down(local_max, offset);
            local_max = cute_max_combine(local_max, other);
        }
        if (lane == 0) {
            y[output_idx] = local_max;
        }
    }
}

torch::Tensor cute_max_reduce(torch::Tensor x, int64_t dim)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 3, "x must be a 3D tensor");
    TORCH_CHECK(dim >= 0 && dim < 3, "dim must be 0, 1, or 2");
    TORCH_CHECK(
        x.scalar_type() == at::kFloat ||
        x.scalar_type() == at::kDouble ||
        x.scalar_type() == at::kHalf,
        "supported dtypes are float16, float32, and float64");

    auto x_contiguous = x.contiguous();

    int d0 = static_cast<int>(x_contiguous.size(0));
    int d1 = static_cast<int>(x_contiguous.size(1));
    int d2 = static_cast<int>(x_contiguous.size(2));

    std::vector<int64_t> output_shape;
    if (dim == 0) {
        output_shape = {d1, d2};
    } else if (dim == 1) {
        output_shape = {d0, d2};
    } else {
        output_shape = {d0, d1};
    }

    auto output = torch::empty(output_shape, x.options());
    int output_size = static_cast<int>(output.numel());

    constexpr int threads = 256;
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    AT_DISPATCH_FLOATING_TYPES_AND_HALF(
        x.scalar_type(),
        "cute_max_reduce",
        [&] {
            cute_max_reduce_kernel<scalar_t>
                <<<output_size, threads, (threads / 32) * sizeof(scalar_t), stream>>>(
                    x_contiguous.data_ptr<scalar_t>(),
                    output.data_ptr<scalar_t>(),
                    d0,
                    d1,
                    d2,
                    static_cast<int>(dim),
                    output_size);
        });

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CUTE max-reduction kernel launch failed");

    return output;
}
"""

cute_ext = load_inline(
    name="cute_max_reduce_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_max_reduce"],
    extra_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_max_reduce(x, self.dim)

